Detection uses a tiered approach, from most to least authoritative:

1. The ``DATAHUB_CALLER`` environment variable (explicit override).
2. Known environment-variable signatures in the current process.
3. Generic CI detection via ``CI=true``.
4. The parent process environment (Linux ``/proc``, macOS ``ps eww``).
5. Process-tree heuristics walking the ancestor chain.

The public entrypoint :func:`identify_caller` never raises and always returns a
short, single-line label suitable for embedding in a User-Agent header.
"""

from __future__ import annotations

import functools
import logging
import os
import platform
import subprocess
from typing import List, Optional

logger = logging.getLogger(__name__)

# Explicit override env var. Takes precedence over every other detection tier.
_CALLER_OVERRIDE_ENV = "DATAHUB_CALLER"

# Maximum length of a returned caller label. Keeps the User-Agent header sane
# even if a process name or override value is pathologically long.
_MAX_LABEL_LENGTH = 200

# Timeout (seconds) for the small ``ps`` subprocesses used for process-tree
# inspection. Kept short so detection never noticeably delays CLI startup.
_SUBPROCESS_TIMEOUT = 2.0

# Environment-variable signatures mapped to caller labels. Keys are bare env var
# names for key-presence matching, or "KEY=value" strings for exact matching.
# Ordering is significant: when a parent environment contains several matching
# signatures, the first one wins, so AI coding tools are listed before generic
# CI systems.
_CALLER_SIGNATURES = {
    "CLAUDECODE": "claude-code",
    "CURSOR_TRACE_ID": "cursor",
    "LANGCHAIN_TRACING_V2": "langchain",
    "LANGSMITH_API_KEY": "langchain",
    "LANGGRAPH_API_URL": "langgraph",
    "GITHUB_ACTIONS": "github-actions",
    "JENKINS_URL": "jenkins",
}

# Own-environment signals checked directly against os.environ. Some tools set a
# boolean-ish flag (checked for truthiness), others just export any value at all
# (checked for presence). Order matches _CALLER_SIGNATURES priority.
_ENV_SIGNALS = [
    ("CLAUDECODE", "claude-code", "truthy"),
    ("CURSOR_TRACE_ID", "cursor", "present"),
    ("LANGCHAIN_TRACING_V2", "langchain", "truthy"),
    ("LANGSMITH_API_KEY", "langchain", "present"),
    ("LANGGRAPH_API_URL", "langgraph", "present"),
    ("GITHUB_ACTIONS", "github-actions", "truthy"),
    ("JENKINS_URL", "jenkins", "present"),
]

# Interactive shells used to recognize a plain terminal invocation.
_SHELLS = {"bash", "zsh", "fish", "sh", "dash", "tcsh", "ksh"}

# Values that count as an enabled generic-CI flag.
_CI_TRUE_VALUES = {"true", "1", "yes"}


def _is_truthy(value: str) -> bool:
    return value.strip().lower() not in ("", "0", "false", "no", "off")


def _match_signatures(env_text: str) -> Optional[str]:
    """Return the label of the first _CALLER_SIGNATURES entry present in env_text."""
    for key, label in _CALLER_SIGNATURES.items():
        if "=" in key:
            if key in env_text:
                return label
        elif f"{key}=" in env_text:
            return label
    return None


def _read_parent_env_linux(ppid: int) -> Optional[str]:
    """Read a process's environment from /proc as a newline-separated string."""
    try:
        with open(f"/proc/{ppid}/environ", "rb") as f:
            data = f.read()
    except (PermissionError, FileNotFoundError):
        return None
    return data.replace(b"\0", b"\n").decode("utf-8", errors="replace")


def _read_parent_env_macos(ppid: int) -> Optional[str]:
    """Read a process's environment on macOS via ``ps eww``."""
    try:
        result = subprocess.run(
            ["ps", "eww", "-o", "command=", "-p", str(ppid)],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    return result.stdout


def _get_process_name(pid: int) -> Optional[str]:
    """Return the command basename for a PID (special-casing the Gradle daemon)."""
    try:
        result = subprocess.run(
            ["ps", "-o", "comm=", "-p", str(pid)],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    name = os.path.basename(result.stdout.strip())
    # The Gradle daemon runs as a plain "java" process; disambiguate it via the
    # full command line so terminal detection doesn't mistake it for a shell.
    if name == "java":
        full_command = _get_full_command(pid)
        if full_command and "GradleDaemon" in full_command:
            return "gradle"
    return name


def _get_full_command(pid: int) -> Optional[str]:
    """Return the full command line for a PID, whitespace-stripped."""
    try:
        result = subprocess.run(
            ["ps", "-o", "command=", "-p", str(pid)],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    return result.stdout.strip()


def _get_parent_pid(pid: int) -> Optional[int]:
    """Return the parent PID for a PID, or None at the top of the tree."""
    if pid == 1:
        return None
    try:
        result = subprocess.run(
            ["ps", "-o", "ppid=", "-p", str(pid)],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    try:
        return int(result.stdout.strip())
    except ValueError:
        return None


def _get_ancestor_chain(max_depth: int = 4) -> List[str]:
    """Walk the process tree from this process's parent, collecting names."""
    chain: List[str] = []
    pid = os.getppid()
    for _ in range(max_depth):
        name = _get_process_name(pid)
        if name is None:
            break
        chain.append(name)
        parent = _get_parent_pid(pid)
        if parent is None:
            break
        pid = parent
    return chain


